<script setup lang="ts">
import {entryDisplayName as localizedEntryName} from './runtime-presentation'

import { i18n as controlI18n } from '../app/i18n'
const { t: controlText } = controlI18n.global

import MapFieldPicker from "./map-selection/MapFieldPicker.vue"
import {computed,ref,watch} from 'vue'
import type {RoomView,RoomAction} from '../online/protocol'
import M3CastFields from './M3CastFields.vue'
import type {M3CastChoice} from '../core/m3-spells'
import M3DestinationPreview from './m3/M3DestinationPreview.vue'
import {runtimeDerived,runtimeSpells} from '../core/runtime'
import type {Catalogue} from '../core/engine'
import {M3_EXCLUSIVE_WORLD_SPELLS} from '../core/m3-world-cast'
const props=defineProps<{view:RoomView;characterId:string;content:Catalogue;busy:boolean}>()
const emit=defineEmits<{request:[action:RoomAction,review:boolean,summary:string]}>()
const castChoice=ref<M3CastChoice>({})
const character=computed(()=>props.view.ownCharacters.find(c=>c.id===props.characterId))
const token=computed(()=>props.view.scene?.tokens.find(t=>t.characterId===props.characterId))
const operation=ref<'cast'|'move'|'effect-action'|'portal'>('cast'),key=ref(''),mode=ref(''),objectId=ref(''),targets=ref<string[]>([]),x=ref(0),y=ref(0),height=ref(0),support=ref(''),material=ref(''),willing=ref(false)
const moveMode=ref<'walk'|'climb'|'swim'|'fly'>('fly'),effectId=ref(''),effectAction=ref<'alter-option'|'end-form'|'levitate'|'water-cross'|'stone-exit'>('levitate'),option=ref<'aquatic'|'appearance'|'weapons'>('aquatic'),description=ref(''),portalId=ref(''),enter=ref(true),note=ref(''),creatureType=ref<import('../core/m3-magic-perception').CreatureType>('humanoid'),magical=ref(true)
const grants=computed(()=>character.value?runtimeSpells(character.value,props.content).filter(g=>[...M3_EXCLUSIVE_WORLD_SPELLS,'levitate','enlarge-reduce','faerie-fire','dispel-magic'].includes(g.spell.id)):[])
const grant=computed(()=>grants.value.find(g=>g.key===key.value))
watch(grants,g=>{if(!g.some(g=>g.key===key.value))key.value=g[0]?.key??''},{immediate:true})
watch(()=>grant.value?.key,()=>{const g=grant.value;mode.value=g?.modes[0]??'';objectId.value='';targets.value=g?.spell.id==='feather-fall'?(props.view.scene?.tokens.filter(t=>t.statuses?.some(s=>s.id==='m3-fall')).slice(0,5).map(t=>t.characterId??t.npcId??t.actorId??t.id)??[]):props.characterId?[props.characterId]:[];height.value=g?.spell.id==='floating-disk'?3:token.value?.spatial?.height??0},{immediate:true})
watch(()=>props.characterId+':'+token.value?.id,()=>{const t=token.value;x.value=t?.x??0;y.value=t?.y??0;height.value=t?.spatial?.height??0},{immediate:true})
const objects=computed(()=>props.view.scene?.spatialObjects??[])
const selfOnly=computed(()=>!!objectId.value||['misty-step','floating-disk','rope-trick','meld-into-stone'].includes(grant.value?.spell.id??''))
const effects=computed(()=>character.value?.runtime?.effects?.filter(f=>['alter-self','gaseous-form','levitate','water-walk','meld-into-stone'].includes(f.key))??[])
const movementMultiplier=computed(()=>character.value&&['climb','swim'].includes(moveMode.value)&&runtimeDerived(character.value,props.content).spatialCapabilities[moveMode.value]===0?2:1)
const destination=()=>({x:x.value,y:y.value,height:height.value})
function submit(){
 if(!character.value)return
 const summary=note.value.trim()||'空间操作：'+(grant.value?.spell.name??operation.value)
 let action:Extract<RoomAction,{kind:'spatial'}>['action']
 if(operation.value==='cast')action={operation:'cast',casterId:props.characterId,key:key.value,mode:mode.value,targets:selfOnly.value?[props.characterId]:targets.value,objectId:objectId.value||undefined,to:destination(),materialId:material.value||undefined,choice:grant.value?.spell.id==='arcanist-s-magic-aura'?objectId.value?{option:'false-aura',magical:magical.value}:{option:'mask',creatureType:creatureType.value}:grant.value?.spell.id==='enlarge-reduce'?castChoice.value:undefined,willing:willing.value,confirmed:true,note:summary}
 else if(operation.value==='move')action={operation:'move',entityId:props.characterId,to:destination(),mode:moveMode.value,supportId:support.value||undefined,note:summary}
 else if(operation.value==='effect-action')action={operation:'effect-action',entityId:props.characterId,effectId:effectId.value,action:effectAction.value,choice:{option:option.value,description:description.value},to:destination(),note:summary}
 else action={operation:'portal',entityId:props.characterId,portalId:portalId.value,enter:enter.value,note:summary}
 emit('request',{kind:'spatial',action},true,summary)
}
</script>
<template>
 <details v-if="character&&token" class="m3-player-actions"><summary>{{ controlText('configuration.spatialSpellsAndThreeDimensionalMovement') }}</summary>
  <label>{{ controlText('configurationField.requestOperation') }}<select v-model="operation"><option value="cast">{{ controlText('domain.positionCast') }}</option><option value="move">{{ controlText('configuration.chooseMovementModeAndHeight') }}</option><option value="effect-action">{{ controlText('configuration.followUpOperationsOnExistingEffects') }}</option><option value="portal">{{ controlText('configuration.enterLeaveRopeTrickSpace') }}</option></select></label>
  <template v-if="operation==='cast'"><p v-if="view.scene?.tokens.some(t=>t.statuses?.some(s=>s.id==='m3-fall'))" class="muted">{{ controlText('configuration.someoneIsFallingIfYouHaveAnAvailable') }}</p><label>{{ controlText('configurationField.ownActualSource') }}<select v-model="key"><option v-for="g in grants" :key="g.key" :value="g.key">{{localizedEntryName(g.spell)}}</option></select></label><label>{{ controlText('domain.castingMode') }}<select v-model="mode"><option v-for="m in grant?.modes??[]" :key="m">{{m}}</option></select></label><label>{{ controlText('configurationField.publicActualObject') }}<MapFieldPicker kind="surface"><select v-model="objectId"><option value="">{{ controlText('configuration.noneCreatureDestination') }}</option><option v-for="o in objects" :key="o.id" :value="o.id">{{localizedEntryName(o)}}</option></select></MapFieldPicker></label><label v-if="!selfOnly">{{ controlText('game.actualTarget') }}<MapFieldPicker kind="entity"><select v-model="targets" multiple size="3"><option v-for="t in view.scene?.tokens??[]" :key="t.id" :value="t.characterId??t.npcId??t.actorId??t.id">{{localizedEntryName(t)}}</option></select></MapFieldPicker></label><M3CastFields v-if="grant" :spell-id="grant.spell.id" v-model="castChoice" /><label><input v-model="willing" type="checkbox" /> {{ controlText('configurationField.creatureIsWillingGmVerifies') }}</label><label v-if="grant?.spell.id==='nondetection'">{{ controlText('configurationField.ownActualDiamondDustEntry') }}<select v-model="material"><option value="">{{ controlText('configuration.askTheGmToVerifyMaterialsFirst') }}</option><option v-for="i in character.inventory" :key="i.instanceId" :value="i.instanceId">{{localizedEntryName(content.items.find(x=>x.id===i.itemId))??i.itemId}} ×{{i.quantity}} · {{i.note}}</option></select></label><template v-if="grant?.spell.id==='arcanist-s-magic-aura'"><label v-if="!objectId">{{ controlText('domain.disguiseType') }}<select v-model="creatureType"><option v-for="type in ['aberration','beast','celestial','construct','dragon','elemental','fey','fiend','giant','humanoid','monstrosity','ooze','plant','undead']" :key="type">{{type}}</option></select></label><label v-else><input v-model="magical" type="checkbox" /> {{ controlText('domain.magicAppearance') }}</label></template></template>
  <template v-if="operation==='move'"><label>{{ controlText('game.movementMode') }}<select v-model="moveMode"><option value="walk">{{ controlText('game.walk') }}</option><option value="climb">{{ controlText('game.climb') }}</option><option value="swim">{{ controlText('game.swim') }}</option><option value="fly">{{ controlText('game.fly') }}</option></select></label><label>{{ controlText('configurationField.actualSurfaceLiquid') }}<MapFieldPicker kind="surface"><select v-model="support"><option value="">{{ controlText('configuration.noneGround') }}</option><option v-for="o in objects" :key="o.id" :value="o.id">{{localizedEntryName(o)}}</option></select></MapFieldPicker></label></template>
  <template v-if="operation==='effect-action'"><label>{{ controlText('configurationField.ownActiveEffect') }}<MapFieldPicker kind="region" :locations="token?effects.map(f=>({id:f.id,name:f.name,kind:'region' as const,x:token!.x,y:token!.y,span:token!.span,hitId:token!.id})):[]"><select v-model="effectId"><option v-for="f in effects" :key="f.id" :value="f.id">{{localizedEntryName(f)}}</option></select></MapFieldPicker></label><label>{{ controlText('configurationField.followUpOperation') }}<select v-model="effectAction"><option value="levitate">{{ controlText('configuration.levitateChangeElevation') }}</option><option value="alter-option">{{ controlText('configuration.alterSelfSwitchOption') }}</option><option value="end-form">{{ controlText('configuration.gaseousFormEnd') }}</option><option value="water-cross">{{ controlText('configuration.waterWalkCrossLiquidSurface') }}</option><option value="stone-exit">{{ controlText('configuration.meldIntoStoneExit') }}</option></select></label><template v-if="effectAction==='alter-option'"><label>{{ controlText('domain.shapeOptions') }}<select v-model="option"><option value="aquatic">{{ controlText('domain.aquaticAdaptation') }}</option><option value="appearance">{{ controlText('domain.changeAppearance') }}</option><option value="weapons">{{ controlText('domain.naturalWeapons') }}</option></select></label><label v-if="option==='appearance'">{{ controlText('domain.appearance') }}<textarea v-model="description" rows="2" /></label></template></template>
  <template v-if="operation==='portal'"><label>{{ controlText('configurationField.knownEntrance') }}<MapFieldPicker kind="surface"><select v-model="portalId"><option v-for="o in objects.filter(o=>o.kind==='portal')" :key="o.id" :value="o.id">{{localizedEntryName(o)}}</option></select></MapFieldPicker></label><label><input v-model="enter" type="checkbox" /> {{ controlText('configurationField.enterCancelToLeave') }}</label></template>
  <div v-if="operation!=='portal'" class="m3-position"><label>{{ controlText('game.x') }}<input v-model.number="x" type="number" min="0" max="79" /></label><label>{{ controlText('game.y') }}<input v-model.number="y" type="number" min="0" max="79" /></label><label>{{ controlText('configurationField.heightPositionInLiquidFt') }}<input v-model.number="height" type="number" /></label></div>
  <M3DestinationPreview :scene-id="view.scene?.id" :disabled="busy" @select="p=>{x=p.x;y=p.y;height=p.height}" v-if="token&&view.scene&&operation!=='portal'" :from="token" :to="destination()" :feet="view.scene.grid.feet" :columns="view.scene.grid.columns" :rows="view.scene.grid.rows" :walls="view.scene.walls" :movement="operation==='move'" :multiplier="movementMultiplier" />
  <label>{{ controlText('configurationField.briefNotes') }}<input v-model="note" maxlength="2000" /></label><button :disabled="busy||operation==='cast'&&!grant" @click="submit">{{ controlText('configuration.requestExecutionAfterGmConfirmation') }}</button><p class="muted">{{ controlText('configuration.requestsSpendNoResourcesAfterGmConfirmationResolve') }}</p>
 </details>
</template>
<style scoped>.m3-player-actions{font-size:.85rem;margin:.4rem 0}.m3-player-actions label{display:grid;gap:.25rem;margin:.4rem 0;min-width:0}.m3-player-actions input:not([type=checkbox]),.m3-player-actions select,.m3-player-actions textarea{width:100%;max-width:100%;min-width:0}.m3-position{display:grid;grid-template-columns:1fr 1fr;gap:.5rem}.m3-player-actions button{min-height:44px}@media(max-width:500px){.m3-position{grid-template-columns:1fr}}</style>
